$ErrorActionPreference='Stop';Import-Module (Join-Path $PSScriptRoot 'src/HousePrototype.psm1') -Force -DisableNameChecking
$s=New-HouseSession $PSScriptRoot 6001;$seen=@();1..20|ForEach-Object{$r=Invoke-HouseTurn $s 'look around';$seen+=@($r.narration_packet.ambient)}
for($i=0;$i-lt$seen.Count;$i++){for($j=[Math]::Max(0,$i-5);$j-lt$i;$j++){if($seen[$i]-eq$seen[$j]){throw "Ambient repeated inside six-turn cooldown: $($seen[$i])"}}}
$s=New-HouseSession $PSScriptRoot 6001;$null=Invoke-HouseTurn $s 'circle house';$entry=Invoke-HouseTurn $s 'go cellar';$eventTurn=Invoke-HouseTurn $s 'look at the rope';if(-not$eventTurn.state.house_state.events.intruder_present-or-not$eventTurn.state.house_state.events.intruder_event_fired){throw 'Intruder event did not latch.'};if(@($eventTurn.narration_packet.events).Count-ne1){throw 'Intruder event did not use the event channel.'};if((@($eventTurn.narration_packet.ambient)-join' ')-match'notably silent'){throw 'Silent ambient remained eligible after audible event.'};$again=Invoke-HouseTurn $s 'look at the rope';if(@($again.narration_packet.events).Count){throw 'Intruder event fired more than once.'};$saved=Export-HouseSave $s;$loaded=Import-HouseSave $PSScriptRoot $saved;if(-not$loaded.HouseEvents.intruder_present){throw 'Intruder event state did not survive save/load.'}
Write-Host 'House ambient/event tests passed.'
